const message = $json.message || {};
const chatId = message.chat?.id;
const text = String(message.text || '').trim();
const lower = text.toLowerCase();
const store = $getWorkflowStaticData('global');
store.sessions ||= {};
const key = String(chatId);
let session = store.sessions[key] || { step: 'menu', flow: '', data: {} };

const menu = () => [
  'Hello! I am the Co.Here Community Information Assistant.',
  '',
  'Choose an option by sending its number:',
  '1. View current community information',
  '2. Submit an update or event',
  '3. Check submission status',
  '4. Submit a new community',
  '5. How this service works',
].join('\n');

const saveReply = (step, reply) => {
  session.step = step;
  store.sessions[key] = session;
  return [{ json: { action: 'reply', chat_id: chatId, reply } }];
};

const reset = () => {
  session = { step: 'menu', flow: '', data: {} };
  store.sessions[key] = session;
};

const cleanOptional = (value) => ['skip', 'none', 'n/a', 'no'].includes(value.toLowerCase()) ? '' : value;

const summary = () => {
  const d = session.data;
  return [
    'Please review your submission:',
    '',
    'Community: ' + (d.community_name || 'Not provided'),
    'Area: ' + (d.area || 'Not provided'),
    'Type: ' + (d.update_type || 'Not provided'),
    'Details: ' + (d.proposed_update || 'Not provided'),
    'Date/time: ' + (d.schedule || 'Not provided'),
    'Location: ' + (d.location || 'Not provided'),
    'Link: ' + (d.link || 'Not provided'),
    'Organiser: ' + (d.organiser_name || 'Not provided'),
    'Contact: ' + (d.contact || 'Not provided'),
    '',
    'Send CONFIRM to submit, EDIT to restart, or CANCEL.',
  ].join('\n');
};

if (!chatId) return [];

if (['/start', 'start', 'hi', 'hello', 'hi cohere', 'menu', '/menu'].includes(lower)) {
  reset();
  return saveReply('menu', menu());
}

if (lower === 'cancel') {
  reset();
  return saveReply('menu', 'Your current entry was cancelled.\n\n' + menu());
}

switch (session.step) {
  case 'menu':
    if (lower === '1') return saveReply('lookup_name', 'Enter the community name you want to view.');
    if (lower === '2') {
      session.flow = 'update'; session.data = {};
      return saveReply('update_name', 'What is the name of the existing community?');
    }
    if (lower === '3') return saveReply('status_reference', 'Enter your submission reference, for example TG-123456.');
    if (lower === '4') {
      session.flow = 'new'; session.data = {};
      return saveReply('new_type', 'What type of community is this?\nExample: sports, arts, language, family support or wellbeing.');
    }
    if (lower === '5') return saveReply('menu', 'Community organisers can view approved information or submit changes. Confirmed submissions enter the staff Review Queue. Nothing is published automatically.\n\n' + menu());
    return saveReply('menu', 'Please send a number from 1 to 5.\n\n' + menu());

  case 'lookup_name':
    delete store.sessions[key];
    return [{ json: { action: 'lookup', chat_id: chatId, lookup_name: text } }];

  case 'status_reference':
    delete store.sessions[key];
    return [{ json: { action: 'status', chat_id: chatId, reference: text.toUpperCase() } }];

  case 'update_name':
    session.data.community_name = text;
    return saveReply('update_area', 'Which town or area is the community in?');
  case 'update_area':
    session.data.area = text;
    return saveReply('update_kind', 'What are you updating?\n1. Event or activity\n2. Community profile');
  case 'update_kind':
    if (!['1', '2'].includes(lower)) return saveReply('update_kind', 'Please send 1 for an event/activity or 2 for a community profile.');
    session.data.update_type = lower === '1' ? 'Event update' : 'Community profile update';
    return saveReply('update_details', lower === '1' ? 'What is the event name and what has changed?' : 'Describe the information that should be changed.');
  case 'update_details':
    session.data.proposed_update = text;
    session.data.description = text;
    return saveReply('update_schedule', 'Enter the event date and time. If this does not apply, send SKIP.');
  case 'update_schedule':
    session.data.schedule = cleanOptional(text);
    return saveReply('update_venue_choice', 'Where will it happen?\n1. Usual community venue\n2. Another location');
  case 'update_venue_choice':
    if (lower === '1') {
      session.data.location = 'Usual community venue';
      return saveReply('shared_link', 'Add a website or map link, or send SKIP.');
    }
    if (lower === '2') return saveReply('update_location', 'Enter the venue name or full location.');
    return saveReply('update_venue_choice', 'Please send 1 for the usual venue or 2 for another location.');
  case 'update_location':
    session.data.location = text;
    return saveReply('shared_link', 'Add a website or map link, or send SKIP.');

  case 'new_type':
    session.data.category = text;
    session.data.update_type = 'New community';
    return saveReply('new_name', 'What is the community or group name?');
  case 'new_name':
    session.data.community_name = text;
    return saveReply('new_area', 'Which town or area is it in?');
  case 'new_area':
    session.data.area = text;
    return saveReply('new_description', 'Briefly describe what the community offers.');
  case 'new_description':
    session.data.description = text;
    session.data.proposed_update = text;
    return saveReply('new_schedule', 'Enter its regular date and time, or send SKIP if unknown.');
  case 'new_schedule':
    session.data.schedule = cleanOptional(text);
    return saveReply('new_location', 'Enter the venue or location, or send SKIP if unknown.');
  case 'new_location':
    session.data.location = cleanOptional(text);
    return saveReply('shared_link', 'Add a website or map link, or send SKIP.');

  case 'shared_link':
    session.data.link = cleanOptional(text);
    return saveReply('shared_organiser', 'Who is submitting this information? Enter the organiser\'s name.');
  case 'shared_organiser':
    session.data.organiser_name = text;
    return saveReply('shared_contact', 'Enter a contact email or phone number, or send SKIP.');
  case 'shared_contact':
    session.data.contact = cleanOptional(text);
    return saveReply('confirm', summary());
  case 'confirm':
    if (lower === 'confirm') {
      const payload = { ...session.data, telegram_user: message.from?.username || message.from?.first_name || 'Telegram organiser' };
      delete store.sessions[key];
      return [{ json: { action: 'submit', chat_id: chatId, ...payload } }];
    }
    if (lower === 'edit') {
      const flow = session.flow;
      session.data = {};
      return flow === 'new'
        ? saveReply('new_type', 'Let\'s restart. What type of community is this?')
        : saveReply('update_name', 'Let\'s restart. What is the existing community name?');
    }
    return saveReply('confirm', 'Please send CONFIRM, EDIT or CANCEL.\n\n' + summary());
  default:
    reset();
    return saveReply('menu', menu());
}

const q = String($('Guided Conversation').item.json.lookup_name || '').toLowerCase();
const rows = $json.communities || [];
const found = rows.find(r => String(r.name).toLowerCase().includes(q));
const reply = found ? `Approved community information

Name: ${found.name}
Area: ${found.area}
Category: ${found.category}
Schedule: ${found.schedule}
Location: ${found.location}
Contact: ${found.contact}
Status: ${found.health}` : `I could not find an approved record for “${$('Guided Conversation').item.json.lookup_name}”. A Community Liaison can help.`;
return [{json:{chat_id:$('Guided Conversation').item.json.chat_id,reply}}];

const ref = String($('Guided Conversation').item.json.reference || '').toUpperCase();
const rows = $json.submissions || [];
const found = rows.find(r => String(r.reference).toUpperCase() === ref);
const reply = found ? `Submission ${found.reference}\nCommunity: ${found.communityName}\nStatus: ${found.status}\nSubmitted by: ${found.submittedBy}` : `I could not find submission ${ref}. Please check the reference or contact a Community Liaison.`;
return [{json:{chat_id:$('Guided Conversation').item.json.chat_id,reply}}];
